#!/usr/bin/env python3
"""One editable sheet, automatic drafts, fixed cost columns, details and mobile layout."""
from pathlib import Path
import os,secrets,subprocess,tempfile,csv,io
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
def main():
 with tempfile.TemporaryDirectory(prefix='scm-draft-ui-') as tmp,sync_playwright() as pw:
  password=secrets.token_urlsafe(24)
  code="import {createApp} from './server.mjs';const app=createApp({dbPath:process.env.LOGISTICS_DB_PATH,secureCookies:false});app.initializeAdmin({username:'draftadmin',password:process.env.SCM_TEST_PASSWORD});app.server.listen(0,'127.0.0.1',()=>console.log(app.server.address().port));process.on('SIGTERM',()=>app.close().then(()=>process.exit(0)));"
  process=subprocess.Popen(['node','--input-type=module','-e',code],cwd=ROOT,env={**os.environ,'LOGISTICS_DB_PATH':str(Path(tmp)/'test.sqlite'),'SCM_TEST_PASSWORD':password},stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
  try:
   port=process.stdout.readline().strip();assert port.isdigit();browser=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=browser.new_page(viewport={'width':1440,'height':1050});errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
   page.add_init_script("const actualConfirm=window.confirm.bind(window);window.confirm=m=>/^(등록을|수정을) 확정하시겠습니까/.test(String(m))?true:actualConfirm(m);")
   def state():return page.evaluate("async()=>(await(await fetch('/api/state')).json()).state")
   def drafts():return page.evaluate("async()=>(await(await fetch('/api/drafts')).json()).drafts")
   page.goto('http://127.0.0.1:'+port);page.wait_for_selector('#login-form');page.fill('[name=username]','draftadmin');page.fill('[name=password]',password);page.click('#login-form button');page.wait_for_selector('#start-empty');page.click('#start-empty');page.wait_for_selector('.kpi')
   page.click('nav [data-view=locations]');page.fill('#center-add [name=name]','임시저장센터');page.click('#center-add button');page.wait_for_selector('[data-center-country]')
   page.click('nav [data-view=stores]');page.fill('#group-add [name=name]','온라인');page.click('#group-add button');page.wait_for_function("document.querySelector('#store-add [name=groupId]').options.length>0");page.fill('#store-add [name=code]','C001');page.fill('#store-add [name=name]','Agent _예스아시아');page.click('#store-add button');page.wait_for_selector('[data-store-record]')
   page.click('nav [data-view=entry]');page.click('[data-center-input=truck]');page.fill('#center-charge-entry [name=month]','2026-11');page.select_option('#center-charge-entry [name=mode]','reverse');page.locator('#charge-paste-box summary').click();page.select_option('#charge-paste-order','value-first');page.fill('#charge-paste','별도명\t66000\t1\n예스아시아\t88000\t2');assert page.locator('.center-charge-table').count()==1;assert page.locator('[data-sheet-source=paste]').count()==2;assert '확인 필요 1행' in page.locator('#charge-progress').inner_text();assert state()['costs']==[]
   page.locator('[data-sheet-source=paste] [data-store-search]').first.fill('예스아시아');page.locator('[data-sheet-source=paste] [data-store-search]').first.press('Enter');page.fill('[data-paste-number="0"][data-paste-column="1"]','77000');page.fill('[data-paste-number="0"][data-paste-column="2"]','2');page.fill('[data-paste-memo="0"]','첫 운송');assert '확인 필요 0행' in page.locator('#charge-progress').inner_text();assert '165,000' in page.locator('#charge-total').inner_text();assert '38,500' in page.locator('[data-paste-calculated="0"]').inner_text()
   page.wait_for_function("document.querySelector('[data-draft-message]').textContent.includes('자동 임시 저장 완료')");assert len(drafts())==1 and state()['costs']==[]
   page.once('dialog',lambda d:d.accept());page.reload();page.wait_for_selector('.kpi');page.click('nav [data-view=entry]');page.click('[data-center-input=truck]');page.once('dialog',lambda d:d.accept());page.click('[data-draft-load]');page.wait_for_function("document.querySelectorAll('[data-sheet-source=paste]').length===2");assert page.locator('[data-paste-memo="0"]').input_value()=='첫 운송'
   page.click('[data-sheet-remove="paste:1"]');assert page.locator('[data-sheet-source=paste]').count()==1;page.click('#charge-add');page.locator('[data-sheet-source=manual] [data-store-search]').fill('C001');page.locator('[data-sheet-source=manual] [data-store-search]').press('Enter');page.locator('[data-sheet-source=manual] [data-charge-field=quantity]').fill('1');page.locator('[data-sheet-source=manual] [data-charge-field=amount]').fill('50000');assert page.locator('.center-charge-table').count()==1;assert '127,000' in page.locator('#charge-total').inner_text()
   page.click('#center-charge-entry button[type=submit]');page.wait_for_selector('[data-edit]');assert len(state()['costs'])==2;assert sum(r['amount'] for r in state()['costs'])==127000;assert any(r['memo']=='첫 운송' for r in state()['costs']);page.wait_for_timeout(1200);assert drafts()==[]
   page.click('nav [data-view=costs]');page.click('[data-cost-columns=compact]');assert page.locator('#cost-records-table th').count()==8;assert page.locator('#cost-records-table th[data-cost-column=store]').evaluate("e=>getComputedStyle(e).position")=='sticky';assert page.locator('#cost-records-table th[data-cost-column=actions]').evaluate("e=>getComputedStyle(e).position")=='sticky'
   page.locator('[data-cost-detail]').first.click();page.wait_for_selector('#cost-details-dialog[open]');assert '메모' in page.locator('#cost-details-dialog').inner_text();page.click('[data-details-close]');page.click('[data-cost-columns=detailed]');assert page.locator('#cost-records-table th').count()>8;page.click('[data-cost-columns=compact]');assert page.locator('#cost-records-table th').count()==8
   page.click('nav [data-view=entry]');page.click('[data-center-input=truck]');page.fill('#center-charge-entry [name=month]','2026-12');page.select_option('#center-charge-entry [name=mode]','amount');page.fill('[data-charge-field=amount]','1234');page.click('[data-center-input=box]');page.wait_for_function("[...document.querySelectorAll('[data-draft-load]')].length>0");page.wait_for_timeout(1000);assert any(d['slot']=='entry:charges:truck' for d in drafts())
   # A failed draft request stays visible and can be retried without writing costs.
   page.route('**/api/drafts',lambda route:route.abort() if route.request.method=='PUT' else route.continue_());page.fill('[data-charge-field=quantity]','1');page.fill('[data-charge-field=price]','10');page.wait_for_function("document.querySelector('[data-draft-message]').textContent.includes('임시 저장 실패')");assert len(state()['costs'])==2;page.unroute('**/api/drafts');page.click('[data-draft-save]');page.wait_for_function("document.querySelector('[data-draft-message]').textContent.includes('임시 저장했습니다')");assert len(drafts())==2
   page.set_viewport_size({'width':390,'height':844});assert page.evaluate('document.documentElement.scrollWidth')<=390;assert page.locator('.entry-save-bar').evaluate("e=>getComputedStyle(e).position")=='sticky'
   if os.environ.get('UX_SCREENSHOT'):page.set_viewport_size({'width':1440,'height':1050});page.evaluate('window.scrollTo(0,0)');page.screenshot(path=os.environ['UX_SCREENSHOT'],full_page=True)
   assert not errors,errors;browser.close();print('PASS: one editable input/paste sheet + inline resolution/numbers/memo + error progress + automatic private drafts + reload + mixed-row save + no late draft resurrection + compact/detailed columns + fixed store/actions + read-only details + auto-save across tab switch + mobile sticky save bar')
  finally:
   process.terminate()
   try:process.wait(timeout=10)
   except subprocess.TimeoutExpired:process.kill();process.wait()
if __name__=='__main__':main()
